Method.Source:
/// <summary>
///     AVA <c>updateAVAEmailInvoiceFromCustAccount</c> method.
///     AVA - Schneider 15.03.2024
/// </summary>
/// <param name="_custAccount">
///     <c>CustAccount</c> as type
/// </param>
/// <param name="_forupdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>AVAEmailInvoice</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public AVAEmailInvoice updateAVAEmailInvoiceFromCustAccount(CustAccount _custAccount,
                                                            boolean     _forupdate  = false )
{
    AVAEmailInvoice retVal;

    CustTable       locCustTable;

    if(_custAccount)
    {
        locCustTable = CustTable::find(_custAccount);

        retVal = locCustTable.AVAEmailInvoice;
    }

    if(retVal)
    {
        this.AVAEmailInvoice = retVal;

        if(_forupdate)
        {
            ttsbegin;
            this.selectForUpdate(_forupdate);
            this.update();
            ttscommit;
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>updateAVAEmailInvoiceToCustAccount</c> method.
///     AVA - Schneider 15.03.2024
/// </summary>
/// <param name="_custAccount">
///     <c>CustAccount</c> as type
/// </param>
/// <param name="_forupdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>AVAEmailInvoice</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public AVAEmailInvoice updateAVAEmailInvoiceToCustAccount(  CustAccount _custAccount,
                                                            boolean     _forupdate  = false )
{
    AVAEmailInvoice retVal;

    CustTable       locCustTable;

    if(this.AVAEmailInvoice)
    {
        if(_custAccount)
        {
            locCustTable = CustTable::find(_custAccount);
            if(locCustTable.RecId)
            {
                locCustTable.AVAEmailInvoice = this.AVAEmailInvoice;

                retVal = locCustTable.AVAEmailInvoice;

                if(_forupdate)
                {
                    ttsbegin;
                    locCustTable.selectForUpdate(_forupdate);
                    locCustTable.update();
                    ttscommit;
                }
            }
        }
    }
    return retVal;
}
